namespace scratchbird::engine::sblr{namespace{template<class A>bool nz(const A&a){return std::any_of(a.begin(),a.end(),[](auto b){return b;});}void p16(auto&o,uint16_t v){o.push_back(v);o.push_back(v>>8);}void p32(auto&o,uint32_t v){for(int i=0;i<4;i++)o.push_back(v>>(8*i));}void p64(auto&o,uint64_t v){for(int i=0;i<8;i++)o.push_back(v>>(8*i));}uint16_t u16(const uint8_t*p){return p[0]|p[1]<<8;}uint32_t u32(const uint8_t*p){uint32_t v=0;for(int i=3;i>=0;i--)v=v*256+p[i];return v;}uint64_t u64(const uint8_t*p){uint64_t v=0;for(int i=7;i>=0;i--)v=v*256+p[i];return v;}void put(auto&o,const auto&a){o.insert(o.end(),a.begin(),a.end());}void get(const uint8_t*p,auto&a){std::copy(p,p+a.size(),a.begin());}bool hd(const uint8_t*b,size_t n,const char*m,size_t z){return n==z&&std::equal(m,m+4,b)&&b[4]==1&&!b[5]&&u16(b+6)==z&&u32(b+8)==z&&!u32(b+12);}auto H(const char*d,std::vector<uint8_t>b,bool neutral=false){if(neutral&&b.size()>3)b[3]=0;std::vector<uint8_t>m(d,d+std::char_traits<char>::length(d));m.insert(m.end(),b.begin(),b.end());return scratchbird::core::hash::ComputeSha256Digest(m).digest;}bool bound(uint8_t s,uint16_t n,const std::array<uint8_t,32>&b){return(s==0&&n==0&&!nz(b))||(s==1&&n&&n<=32&&!std::any_of(b.begin()+n,b.end(),[](auto x){return x;}));}}
std::vector<uint8_t>EncodeSblrReadRangeRequestV1(const SblrReadRangeRequestV1&v){if(!nz(v.receipt)||!v.occurrence||!v.range_occurrence)return{};std::vector<uint8_t>o{'R','R','Q','R'};p16(o,1);p16(o,64);p32(o,64);p32(o,0);put(o,v.receipt);p64(o,v.occurrence);p32(o,v.range_occurrence);o.insert(o.end(),20,0);return o;}bool DecodeSblrReadRangeRequestV1(const uint8_t*b,size_t n,SblrReadRangeRequestV1*out,std::string*d){if(!out||!hd(b,n,"RRQR",64)){if(d)*d="RRQR invalid";return false;}SblrReadRangeRequestV1 v;get(b+16,v.receipt);v.occurrence=u64(b+32);v.range_occurrence=u32(b+40);if(std::any_of(b+44,b+64,[](auto x){return x;})||EncodeSblrReadRangeRequestV1(v).empty())return false;*out=v;return true;}
std::vector<uint8_t>EncodeSblrReadRangeDescriptorV1(const SblrReadRangeDescriptorV1&v,bool op){if(!nz(v.descriptor)||!v.descriptor_generation||!nz(v.relation)||!v.relation_generation||!nz(v.index)||!v.index_generation||!nz(v.schema)||!v.schema_generation||!nz(v.mga)||!v.mga_generation||!nz(v.security)||!v.security_generation||!nz(v.key_type)||!nz(v.codec)||!v.codec_generation||!bound(v.lower_state,v.lower_length,v.lower)||!bound(v.upper_state,v.upper_length,v.upper)||v.inclusivity>3||(v.direction!=1&&v.direction!=2)||!v.maximum_rows||v.maximum_rows>65535||!nz(v.collation)||!v.collation_generation||!v.availability_generation)return{};std::vector<uint8_t>o{'R','R','G',static_cast<uint8_t>(op?'O':'D')};p16(o,1);p16(o,404);p32(o,404);p32(o,0);put(o,v.descriptor);p64(o,v.descriptor_generation);put(o,v.relation);p64(o,v.relation_generation);put(o,v.index);p64(o,v.index_generation);put(o,v.schema);p64(o,v.schema_generation);put(o,v.mga);p64(o,v.mga_generation);put(o,v.security);p64(o,v.security_generation);put(o,v.key_type);put(o,v.codec);p64(o,v.codec_generation);o.push_back(v.lower_state);o.push_back(v.upper_state);o.push_back(v.inclusivity);o.push_back(v.direction);p16(o,v.lower_length);p16(o,v.upper_length);p32(o,v.maximum_rows);put(o,v.lower);put(o,v.upper);auto ls=H("ScratchBird.SblrReadRangeLower.V1",std::vector<uint8_t>(v.lower.begin(),v.lower.begin()+v.lower_length));auto us=H("ScratchBird.SblrReadRangeUpper.V1",std::vector<uint8_t>(v.upper.begin(),v.upper.begin()+v.upper_length));if(nz(v.lower_sha)&&v.lower_sha!=ls)return{};if(nz(v.upper_sha)&&v.upper_sha!=us)return{};put(o,ls);put(o,us);put(o,v.collation);p64(o,v.collation_generation);auto e=H("ScratchBird.SblrReadRangeDescriptor.V1",o,true);if(nz(v.evidence)&&v.evidence!=e)return{};put(o,e);p64(o,v.availability_generation);return o;}
bool DecodeSblrReadRangeDescriptorV1(const uint8_t*b,size_t n,SblrReadRangeDescriptorV1*out,std::string*d,bool op){if(!out||!hd(b,n,op?"RRGO":"RRGD",404)){if(d)*d="RRG descriptor invalid";return false;}SblrReadRangeDescriptorV1 v;get(b+16,v.descriptor);v.descriptor_generation=u64(b+32);get(b+40,v.relation);v.relation_generation=u64(b+56);get(b+64,v.index);v.index_generation=u64(b+80);get(b+88,v.schema);v.schema_generation=u64(b+104);get(b+112,v.mga);v.mga_generation=u64(b+128);get(b+136,v.security);v.security_generation=u64(b+152);get(b+160,v.key_type);get(b+176,v.codec);v.codec_generation=u64(b+192);v.lower_state=b[200];v.upper_state=b[201];v.inclusivity=b[202];v.direction=b[203];v.lower_length=u16(b+204);v.upper_length=u16(b+206);v.maximum_rows=u32(b+208);get(b+212,v.lower);get(b+244,v.upper);get(b+276,v.lower_sha);get(b+308,v.upper_sha);get(b+340,v.collation);v.collation_generation=u64(b+356);get(b+364,v.evidence);v.availability_generation=u64(b+396);if(EncodeSblrReadRangeDescriptorV1(v,op).empty())return false;*out=v;return true;}
std::vector<uint8_t>EncodeSblrReadRangeResultV1(const SblrReadRangeResultV1&v){if(!nz(v.descriptor)||!v.descriptor_generation||!nz(v.relation)||!nz(v.batch)||v.eof>1||!nz(v.batch_sha)||!nz(v.continuation)||!v.availability_generation)return{};std::vector<uint8_t>o{'R','R','R','S'};p16(o,1);p16(o,184);p32(o,184);p32(o,0);put(o,v.descriptor);p64(o,v.descriptor_generation);put(o,v.relation);put(o,v.batch);p32(o,v.rows);o.push_back(v.eof);o.insert(o.end(),3,0);put(o,v.batch_sha);put(o,v.continuation);p64(o,v.availability_generation);auto e=H("ScratchBird.SblrReadRangeResult.V1",o);if(nz(v.evidence)&&v.evidence!=e)return{};put(o,e);return o;}bool DecodeSblrReadRangeResultV1(const uint8_t*b,size_t n,SblrReadRangeResultV1*out,std::string*d){if(!out||!hd(b,n,"RRRS",184)){if(d)*d="RRRS invalid";return false;}SblrReadRangeResultV1 v;get(b+16,v.descriptor);v.descriptor_generation=u64(b+32);get(b+40,v.relation);get(b+56,v.batch);v.rows=u32(b+72);v.eof=b[76];get(b+80,v.batch_sha);get(b+112,v.continuation);v.availability_generation=u64(b+144);get(b+152,v.evidence);if(std::any_of(b+77,b+80,[](auto x){return x;})||EncodeSblrReadRangeResultV1(v).empty())return false;*out=v;return true;}}
